// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: call SetMinSum, SetLogFile, Initialized
        vm.prank(address(0));
        c.SetMinSum(0.5 ether);
        vm.prank(address(0));
        c.SetLogFile(address(0xdead));
        vm.prank(address(0));
        c.Initialized();

        // User deposits 1 ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Deposit{value: 1 ether}();

        // User tries to collect 0.5 ether
        vm.prank(user);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0.5 ether));
        assertTrue(ok && c.balances(user) == 0.5 ether && address(c).balance == 0.5 ether);
    }
}

