pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Reference: SetMinSum reverts before Initialized; buggy version allows it
        // So after Initialized, buggy version will have MinSum = 5, reference won't
        vm.deal(address(0x1), 100);

        // Step 1: Call Initialized in both versions
        c.Initialized();

        // Step 2: Try to set MinSum. In reference, it reverts because initialized is true.
        // In buggy version, it succeeds (because it checks !intitalized, which is false, so no revert).
        bool ok;
        try c.SetMinSum(5) { ok = true; } catch { ok = false; }

        // If reference version, ok should be false (revert). But we need to check the effect.
        // Instead, we observe MinSum getter: reference will still be 0, buggy will be 5.
        // To make assertion fail on buggy, we need Collect to succeed but reference revert?
        // Actually easier: check that in reference MinSum stays default 0, in buggy it's 5.

        // But we want a single assertion. Let's use the effect on Collect behavior:
        // Collect requires balances[msg.sender] >= MinSum. With MinSum=0 (reference) 
        // a deposit of 1 allows Collect(1). With MinSum=5 (buggy), deposit of 1 fails Collect.

        vm.prank(address(0x1));
        c.Deposit{value: 1}();

        uint256 minSum = c.MinSum();
        // In reference, minSum == 0; in buggy, minSum == 5
        // If minSum == 0, Collect(1) should succeed; if minSum == 5, it should revert
        bool collectOk;
        vm.prank(address(0x1));
        try c.Collect(1) { collectOk = true; } catch { collectOk = false; }

        // The assertion: the reference has MinSum = 0, so Collect succeeds (collectOk true).
        // The buggy has MinSum = 5, so Collect fails (collectOk false).
        // So we assert collectOk is true: passes on reference, fails on buggy.
        assertTrue(collectOk);
    }
}

