pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 100
        c.SetMinSum(100);
        // Initialize
        c.Initialized();
        // Fund an actor with 1 ether
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        // Actor deposits 1 wei
        vm.prank(actor);
        c.Deposit{value: 1}();
        // Now actor's balance is 1 wei, MinSum is 100 (reference) or 0 (modified)
        // Collect(0) should revert in reference because 1 >= 100 is false
        // but succeed in modified because 1 >= 0 is true
        bool ok;
        vm.prank(actor);
        try c.Collect(0) { ok = true; } catch { ok = false; }
        // Reference: Collect reverts -> ok == false, so assertTrue(!ok) passes
        // Modified: Collect succeeds -> ok == true, so assertTrue(!ok) fails
        assertTrue(!ok);
    }
}

