        // Step 2: SetMinSum(1e19) – in reference sets MinSum=1e19, in bug sets MinSum=0
        c.SetMinSum(1e19);
        // Step 3: user deposits 1 ether
        uint depositAmount = 1 ether;
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();
        // Step 4: user tries to collect 0.5 ether
