pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a LogFile contract to set as Log in the reference version
        address logAddr = address(new LogFile());
        // Set up initial state
        c.SetMinSum(10);
        c.SetLogFile(logAddr);
        c.Initialized();

        address user = address(0x1);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Deposit{value: 5 ether}();

        // Now call Collect: reference should succeed, bug should revert
        uint256 balanceBefore = c.balances(user);
        vm.prank(user);
        bool ok;
        try c.Collect(5) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = c.balances(user);

        // In reference, Collect succeeds and balance decreases by 5
        // In bug, Collect reverts so balance stays same
        assertTrue(ok);
        assertEq(balanceAfter, balanceBefore - 5);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

