pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. setup: initialize MinSum and LogFile
        c.SetMinSum(1 ether);
        address logAddr = address(new LogFile());
        c.SetLogFile(logAddr);
        c.Initialized();

        // 2. deposit 2 ether from some user
        address user = address(0x123);
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.Deposit{value: 2 ether}();

        // 3. now Collect 1 ether
        vm.prank(user);
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // The buggy version pushes no log entry for Collect; History[0] exists from Deposit, but History[1] would be out-of-bounds.
        // The reference pushes a second entry; buggy does not. We assert that the second entry's Data field equals "Collect".
        // To check History[1], we need to get the entire History array length first.
        (bool lengthOk, bytes memory lengthData) = address(c).staticcall(abi.encodeWithSignature("Log()"));
        assertTrue(lengthOk); // but simpler: directly query History via LogFile instance named as public variable? No, Log is LogFile type, not a getter. Use the known logAddr.
        // Simpler: check revert of Collect? No, both succeed. The difference is log contents. We'll use the LogFile contract's History array through the address.
        // Since LogFile is deployed separately and address known, we can call its public getter:
        LogFile logContract = LogFile(logAddr);
        uint len = logContract.History.length;
        // In reference: 2 entries (deposit + collect), in bug: 1 entry (deposit only)
        // So we assert that len == 2, which fails for buggy (len==1)
        assertEq(len, 2);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

